arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchiveEntry now respects the UTF-8 flag and
        // defaults to UTF-8 encoding for entry names. Our legacy Java consumer reads
        // filenames in Shift-JIS, so we must explicitly specify the encoding to avoid
        // the UTF-8 flag being set in the entry header.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding(932)
            ?? Encoding.UTF8;
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

